namespace PZ3D {
 static class GameLogAnalyzerTests {
  static int passed;
  static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
  static GameLogReport Analyze(params GameLogInput[] inputs){var t=typeof(GameLogReport).Assembly.GetType("PZ3D.GameLogAnalyzer");Check(t!=null,"generic analyzer exists");try{return (GameLogReport)t.GetMethod("Analyze",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{inputs,CancellationToken.None,null});}catch(TargetInvocationException e){throw e.InnerException;}}
  static GameLogInput Input(string text,string session){return new GameLogInput{Id="source-"+session,Name="console.txt",Kind="imported",SessionKey=session,Encoding="utf-8",Length=text.Length,Open=()=>new StringReader(text)};}
  static GameLogReport Text(string text){return Analyze(Input(text,"one"));}
  static string Attention(GameLogIssue issue){var field=typeof(GameLogIssue).GetField("attention");return field==null?null:(string)field.GetValue(issue);}
  // Catches the screenshot's ERROR label becoming a primary gameplay fault without functional failure evidence.
  static void BoneAttention(){var r=Text("STATE: enter zombie.gameStates.IngameState\nERROR: General f:0 st:0 at ImportedSkeleton.collectBoneFrames > Could not find bone index for node name: \"Body\"\n");var i=r.issues.Single();Check(Attention(i)=="background"&&i.severity=="error"&&i.count==1,"screenshot bone ERROR is retained as background");Check(i.title.Contains("骨骼")&&i.meaning.Contains("Body")&&!i.meaning.Contains("无害"),"bone diagnostic explains node evidence without harmlessness claim");Check(r.state=="entered","background ERROR alone does not imply gameplay malfunction");}
  // Catches exact-message resource variants exhausting the group budget and hiding arbitrary MOD faults.
  static void AttentionBudget(){string flood=string.Join("\n",Enumerable.Range(1,500).Select(x=>"ERROR: General f:0 st:0 at ImportedSkeleton.collectBoneFrames > Could not find bone index for node name: \"Node"+x+"\""))+"\n";var r=Text(flood+"ERROR: unfamiliar callback failed\nLua((MOD:Renamed Fictional Any Pack)).tick(media/lua/client/unique.lua:47)\nERROR: Cannot load world due to WorldDictionary error\n");var bone=r.issues.Single(i=>Attention(i)=="background");Check(bone.count==500&&r.issues.Length==3,"hundreds of bone variants group without dropping core faults");var lua=r.issues.Single(i=>i.mods.Contains("Renamed Fictional Any Pack"));Check(Attention(lua)=="primary"&&lua.frames.Any(f=>f.file=="media/lua/client/unique.lua"&&f.line==47),"unknown useful MOD script frame remains primary after noise");Check(r.state=="failed"&&r.issues.Any(i=>i.type=="world-load"&&Attention(i)=="primary"),"late world failure survives resource flood");Check(bone.evidence.Length>1&&r.reportText.Contains("Node1")&&r.reportText.Contains("Node2")&&r.incomplete&&r.warnings.Any(w=>w.Contains("12")&&w.Contains("采样")),"group export retains examples and reports actual evidence sampling cap");}
  // Catches routine reports being padded with generic disclaimers or an untriggered limits paragraph.
  static void ConciseCopy(){var r=Text("ERROR: Could not find bone index for node name: \"Body\"\n");Check(r.issues.Single().meaning=="未找到节点“Body”的骨骼索引。","bone meaning translates the concrete node message concisely");Check(!r.incomplete&&r.warnings.Length==0&&!r.reportText.Contains("范围限制")&&!r.reportText.Contains("120000"),"small report does not show an unconditional cap paragraph");r=Text("ERROR: unfamiliar subsystem wobble\n");Check(r.issues.Single().meaning=="具体原因待核对。"&&r.issues.Single().title.Contains("unfamiliar subsystem wobble"),"unknown retains concrete title and concise uncertainty");string text="java.lang.RuntimeException: attempted index: health of non-table: null\njava.lang.RuntimeException: Object tried to call nil\nERROR: checksum mismatch\nERROR: Cannot load world\n";r=Text(text);foreach(var issue in r.issues)Check(!new[]{"不等于","尚不能","没有证明","未证明","不能保证","仅凭","不代表"}.Any(s=>(issue.meaning+issue.advice).Contains(s)),"issue copy gives concrete meaning and advice: "+issue.type);Check(!r.summary.Contains("不等于"),"summary contains state and counts without generic principle text");}
  // Catches treating all missing resources alike, including asset traversal and explicitly required failures.
  static void AssetEscalation(){string scan="ERROR: General > AdvancedAnimator$1.visitFileFailed> Exception thrown\njava.nio.file.NoSuchFileException: C:\\fiction\\media\\AnimSets\n";var r=Text(scan+scan+"ERROR: Could not find bone index for node name: \"Body\"\njava.lang.NullPointerException: Required Animation Asset not found: fictional/idle\nGameThread exited\n");Check(r.issues.Any(i=>i.type=="asset-diagnostic"&&Attention(i)=="background"&&i.count==2),"asset directory traversal is distinct background evidence");Check(r.issues.Any(i=>i.type=="missing-resource"&&Attention(i)=="primary"&&i.impact=="blocking")&&r.state=="failed","required asset and terminal exit escalate separately");r=Text("ERROR: Could not find bone index for node name: \"Body\"\nFATAL: Could not find bone index for node name: \"Body\"\nGameThread exited\n");Check(r.issues.Any(i=>Attention(i)=="background")&&r.issues.Any(i=>Attention(i)=="primary"&&i.impact=="blocking")&&r.state=="failed","fatal asset evidence cannot merge into nonfatal background");r=Text("java.nio.file.NoSuchFileException: C:\\fiction\\required.data\n");Check(Attention(r.issues.Single())=="primary","missing file exception without asset traversal context stays primary");}
  // Catches generic title walls, severity-only state upgrades and lost actionable script import evidence.
  static void UnknownAttention(){var r=Text("STATE: enter zombie.gameStates.IngameState\nERROR: unfamiliar subsystem wobble\n");Check(Attention(r.issues.Single())=="review"&&r.state=="entered","unknown error without useful cause is review only");Check(r.issues.Single().title.Contains("unfamiliar subsystem wobble")&&!r.issues.Single().title.Contains("未分类"),"unknown title identifies observed message");r=Text("ERROR: unfamiliar callback failed\nLua((MOD:A Completely New Name)).tick(arbitrary.lua:93)\n");Check(Attention(r.issues.Single())=="primary"&&r.issues.Single().title.Contains("脚本"),"useful unknown script fault is primary with concrete context");r=Text("WARN: require(\"TimedActions/ExampleAction\") failed\n");Check(Attention(r.issues.Single())=="review"&&r.issues.Single().title.Contains("ExampleAction"),"WARN require retains concrete module context without claiming functional failure");r=Text("ERROR: require(\"TimedActions/ExampleAction\") failed\n");Check(Attention(r.issues.Single())=="primary","explicit ERROR module load failure stays actionable");r=Text("WARN: require(\"TimedActions/ExampleAction\") failed\nCaused by: java.lang.RuntimeException: Object tried to call nil\nLua((MOD:Never Listed Pack)).run(example.lua:51)\n");Check(r.issues.Any(i=>Attention(i)=="primary"&&i.type=="lua-call-nil"),"actual Lua exception escalates preceding module warning");foreach(string fault in new[]{"connection-attempt-failed","ERROR: checksum mismatch","ERROR: required mod \"Any Brand New Name\" not found","java.lang.IllegalStateException: operation failed"})Check(Text(fault).issues.Any(i=>Attention(i)=="primary"),"explicit functional fault remains primary: "+fault);}
  // Catches opaque Lua control signals being presented as proven broken gameplay solely because a stack exists.
  static void OpaqueSignals(){var r=Text("STATE: enter zombie.gameStates.IngameState\nse.krka.kahlua.vm.KahluaException: FictionalCaptureCompleted\nLua((MOD:An Arbitrary Medical Addon)).done(MedicalReadouts.lua:99)\n");Check(Attention(r.issues.Single())=="review"&&r.state=="entered","opaque Kahlua signal stays review without assumed gameplay failure");r=Text("ERROR: unfamiliar state Wobble\nLua((MOD:Another Renamed Addon)).tick(context.lua:13)\n");Check(Attention(r.issues.Single())=="review"&&r.issues.Single().title.Contains("脚本"),"script context alone does not prove unfamiliar message is functional fault");}
  // Catches network failure evidence requiring a red ERROR prefix or being assigned to the later successful retry.
  static void NetworkAttention(){var r=Text("connection-lost\n");Check(r.state=="disconnected"&&r.issues.Any(i=>Attention(i)=="primary"&&i.evidence.Any(e=>e.text=="connection-lost")),"network connection loss has primary evidence without ERROR prefix");r=Text("connection-attempt-failed\nconnection-request-accepted\nSTATE: enter zombie.gameStates.IngameState\n");var failure=r.issues.Single();Check(r.state=="entered"&&failure.attemptId==r.attempts[0].id&&r.attempts[0].state=="failed","earlier connection failure does not mark successful retry as runtime issue");Check(failure.phase=="connection"&&failure.impact=="candidate"&&failure.evidence.Length==1&&failure.evidence[0].line==1&&failure.evidence[0].text=="connection-attempt-failed","failed attempt keeps connection phase and only its own evidence across accepted retry");r=Text("connection-attempt-failed\nconnection-request\nconnection-request-accepted\njava.lang.RuntimeException: Object tried to call nil\nLua((MOD:A New Runtime Pack)).tick(runtime.lua:31)\nzombie.gameStates.IngameState.update(IngameState.java:55)\n");failure=r.issues.Single(i=>i.type=="connection-failure");var runtime=r.issues.Single(i=>i.type=="lua-call-nil");Check(r.state=="entered-with-issues"&&failure.phase=="connection"&&failure.impact=="candidate"&&failure.evidence.Length==1&&runtime.attemptId==r.attempts.Last().id&&runtime.phase=="runtime"&&runtime.impact=="runtime","new request isolates old failure while genuine retry Lua fault remains runtime");Check(runtime.evidence.Count(e=>e.line==6&&e.text.Contains("IngameState.update"))==1,"same-attempt runtime frame is retained once");r=Text("connection-attempt-failed\nSTATE: enter zombie.gameStates.IngameState\n");failure=r.issues.Single();Check(r.state=="entered"&&failure.phase=="connection"&&failure.impact=="candidate"&&failure.evidence.Length==1,"direct successful retry does not attach entry evidence to old terminal failure");}
  // Catches borrowing stale metadata time for an undated fault after a recorded network retry.
  static void FaultTimestampAttribution(){var connection=Input("[22-10-26 00:01:00.000] connection-attempt-failed\n[22-10-26 00:02:00.000] connection-request-accepted\n","paired");connection.Id="connections";var console=Input("LOG: metadata time 2026-10-22T00:00:00\njava.lang.RuntimeException: Object tried to call nil\nLua((MOD:Arbitrary Retry Pack)).tick(retry.lua:73)\nzombie.gameStates.IngameState.update(IngameState.java:55)\n","paired");console.Id="console";var r=Analyze(connection,console);var runtime=r.issues.Single(i=>i.type=="lua-call-nil");Check(r.state=="entered-with-issues"&&r.attempts[0].state=="failed"&&runtime.attemptId==r.attempts.Last().id&&runtime.phase=="runtime","undated runtime fault is not attributed to failed attempt by stale metadata timestamp");}
  // Catches different resource contexts merging together or 80 unrelated resources crowding out late primary faults.
  static void DistinctResources(){var r=Text("ERROR: Could not find bone index for node name: \"Body\"\nLua((MOD:First Arbitrary Pack)).load(first.lua:1)\nERROR: Could not find bone index for node name: \"Body\"\nLua((MOD:Second Arbitrary Pack)).load(second.lua:1)\n");Check(r.issues.Length==2&&r.issues.All(i=>Attention(i)=="background"),"resource families preserve distinct MOD and script contexts");string flood=string.Join("\n",Enumerable.Range(1,100).Select(x=>"ERROR: Could not find icon: FictionalIcon"+x))+"\n";r=Text(flood+"java.lang.RuntimeException: Object tried to call nil\nLua((MOD:A Never Listed Name)).run(last.lua:46)\njava.lang.OutOfMemoryError: Java heap space\n");Check(r.issues.Length<=80&&r.incomplete&&r.issues.Any(i=>i.type=="lua-call-nil"&&Attention(i)=="primary")&&r.issues.Any(i=>i.type=="java-heap"&&Attention(i)=="primary"),"late primary faults displace distinct background resources at 80 group cap");r=Text("java.lang.NullPointerException: Could not find bone index for node name: \"Body\"\n");Check(Attention(r.issues.Single())=="primary","actual Java exception cannot be downgraded by bone words in payload");}
  // Catches silently cutting a large export while leaving the result marked complete.
  static void ExportCap(){string text=string.Join("\n",Enumerable.Range(1,60).Select(x=>"ERROR: distinct review "+x+" "+new string('x',760)+"\nat detail alpha "+new string('a',760)+"\nat detail beta "+new string('b',760)+"\nat detail gamma "+new string('c',760)));var r=Text(text);Check(r.reportText.Length<=120000&&r.incomplete&&r.warnings.Any(w=>w.Contains("导出")&&w.Contains("120000")),"large export has bounded length and explicit incomplete cap notice");}
  // Catches an asset diagnostic absorbing a later fatal cause or losing a FATAL header before the exception.
  static void AssetCauseEscalation(){var r=Text("ERROR: Could not find bone index for node name: \"Body\"\nCaused by: java.lang.NullPointerException: Required Animation Asset not found: critical/idle\nGameThread exited\n");Check(r.state=="failed"&&r.issues.Any(i=>Attention(i)=="primary"&&i.impact=="blocking"&&i.evidence.Any(e=>e.text.Contains("critical/idle"))),"required cause escalates earlier background asset block");r=Text("FATAL: General > AdvancedAnimator$1.visitFileFailed> Exception thrown\njava.nio.file.NoSuchFileException: C:\\fiction\\media\\AnimSets\nGameThread exited\n");Check(r.state=="failed"&&r.issues.Any(i=>Attention(i)=="primary"&&i.impact=="blocking"),"fatal scan header survives into exception block");}
  // Catches a stronger later record merging into the first warning and inheriting its review attention/severity.
  static void SeverityEscalation(){var r=Text("WARN: require(\"TimedActions/ExampleAction\") failed\nERROR: require(\"TimedActions/ExampleAction\") failed\n");Check(r.issues.Length==2&&r.issues.Any(i=>Attention(i)=="review"&&i.severity=="warning")&&r.issues.Any(i=>Attention(i)=="primary"&&i.severity=="error"),"same module warning and error preserve their original severity and priority");}
  // Catches assuming a known MOD name, losing B42 script locations, or calling runtime errors join failures.
  static void ArbitraryLua(){var r=Text("ERROR: General > dumping Lua stack trace\nLua((MOD:Unseen Workshop Name)).tick(media/lua/client/fiction.lua:248)\nERROR: General > Exception thrown\njava.lang.RuntimeException: attempted index: health of non-table: null\nLua((MOD:Unseen Workshop Name)).tick(media/lua/client/fiction.lua:248)\nzombie.gameStates.IngameState.update(IngameState.java:1370)\n");var i=r.issues.Single(x=>x.type=="lua-null-index");Check(i.mods.Contains("Unseen Workshop Name"),"arbitrary MOD metadata identified");Check(i.frames.Any(f=>f.file=="media/lua/client/fiction.lua"&&f.line==248),"relative script path and line retained");Check(i.meaning.Contains("health")&&i.meaning.Contains("空"),"null field explained in Chinese");Check(r.state=="entered-with-issues"&&i.phase=="runtime"&&i.impact=="runtime","runtime stack is gameplay evidence, not join failure");Check(i.evidence.Any(e=>e.line==4&&e.text.Contains("attempted index")),"original exception source line retained");}
  // Catches grouping all headers together or counting Lua display copies as independent exceptions.
  static void Grouping(){string block="ERROR: General > dumping Lua stack trace\nLua((MOD:Never Seen)).run(a.lua:12)\nERROR: General > Exception thrown\njava.lang.RuntimeException: Object tried to call nil in run\nLua((MOD:Never Seen)).run(a.lua:12)\n";var r=Text(block+block+"ERROR: General > Exception thrown\njava.lang.RuntimeException: __len not defined for operand\nLua((MOD:Never Seen)).run(b.lua:25)\n");Check(r.issues.Length==2,"distinct exceptions group by message and frames");Check(r.issues.Single(x=>x.type=="lua-call-nil").count==2,"repeated exception count ignores generic and dump headers");Check(r.issues.Single(x=>x.type=="lua-length").frames.Any(f=>f.file=="b.lua"),"separate stack retained");}
  // Catches discarding B41 metadata preceding the Java exception.
